import { revalidateTag } from 'next/cache';
import { getCachedProducts, type Product } from '@/lib/products';

export default async function AdminCatalogPage() {
  const products = await getCachedProducts();

  async function syncCatalog() {
    'use server';
    // Invalidate the "products" cache tag so every view depending on it
    // gets fresh data on its next request.  This returns immediately —
    // the re-fetch happens lazily, keeping the admin UI non-blocking.
    revalidateTag('products');
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui, sans-serif', maxWidth: '800px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' }}>
        <h1 style={{ margin: 0, fontSize: '1.5rem' }}>Product Catalog</h1>
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '0.5rem 1.25rem',
              background: '#0070f3',
              color: '#fff',
              border: 'none',
              borderRadius: '6px',
              cursor: 'pointer',
              fontSize: '0.9rem',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '0.95rem' }}>
        <thead>
          <tr style={{ background: '#f5f5f5' }}>
            <th style={{ textAlign: 'left', padding: '0.6rem 1rem', borderBottom: '2px solid #ddd' }}>ID</th>
            <th style={{ textAlign: 'left', padding: '0.6rem 1rem', borderBottom: '2px solid #ddd' }}>Name</th>
            <th style={{ textAlign: 'left', padding: '0.6rem 1rem', borderBottom: '2px solid #ddd' }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product: Product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #eee' }}>
              <td style={{ padding: '0.6rem 1rem' }}>{product.id}</td>
              <td style={{ padding: '0.6rem 1rem' }}>{product.name}</td>
              <td style={{ padding: '0.6rem 1rem' }}>${product.price}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  );
}

